#!/usr/bin/env python3
"""fleetrun.py -- offline fleet simulator.

Hosts are simulated as local directories: fleet/<hostname>/facts.json with
{"os": ..., "cpu_count": ..., "tags": [...]}.

Usage:
    python3 fleetrun.py [--fleet DIR] --select 'EXPR' -- COMMAND TEMPLATE

Selection predicate language:
    field access : hostname, or any fact key (os, cpu_count, tags, ...)
    comparison   : ==
    membership   : contains   (list membership, or substring for strings)
    boolean      : and, or
    grouping     : parentheses

Command template placeholders:
    {hostname}     -> host name
    {fact:KEY}     -> value of fact KEY (rendered with json.dumps for lists)
Shell braces other than these placeholders are left untouched.
"""

from __future__ import annotations

import argparse
import json
import re
import subprocess
import sys
from pathlib import Path

# --------------------------------------------------------------------------
# Predicate language: tokenizer
# --------------------------------------------------------------------------

TOKEN_RE = re.compile(
    r"""
    \s*(?:
        (?P<lparen>\()
      | (?P<rparen>\))
      | (?P<eq>==)
      | (?P<string>'[^']*'|"[^"]*")
      | (?P<number>-?\d+(?:\.\d+)?)
      | (?P<ident>[A-Za-z_][A-Za-z0-9_.-]*)
    )
    """,
    re.VERBOSE,
)

KEYWORDS = {"and", "or", "contains"}


class PredicateError(ValueError):
    """Raised for any syntax error in a selection expression."""


def tokenize(text: str) -> list[tuple[str, object]]:
    tokens: list[tuple[str, object]] = []
    pos = 0
    while pos < len(text):
        m = TOKEN_RE.match(text, pos)
        if not m or m.end() == pos:
            rest = text[pos:].strip()
            if not rest:
                break
            raise PredicateError(f"unexpected token near: {rest!r}")
        pos = m.end()
        if m.group("lparen"):
            tokens.append(("(", "("))
        elif m.group("rparen"):
            tokens.append((")", ")"))
        elif m.group("eq"):
            tokens.append(("==", "=="))
        elif m.group("string") is not None:
            tokens.append(("literal", m.group("string")[1:-1]))
        elif m.group("number") is not None:
            num = m.group("number")
            tokens.append(("literal", float(num) if "." in num else int(num)))
        elif m.group("ident"):
            name = m.group("ident")
            tokens.append((name if name in KEYWORDS else "field", name))
    return tokens


# --------------------------------------------------------------------------
# Predicate language: recursive-descent parser
#
#   expr     := or_expr
#   or_expr  := and_expr ('or' and_expr)*          (lowest precedence)
#   and_expr := comparison ('and' comparison)*
#   comparison := operand ('==' | 'contains') operand
#              | '(' expr ')'
#   operand  := literal | field
# --------------------------------------------------------------------------


def parse(text: str):
    tokens = tokenize(text)
    if not tokens:
        raise PredicateError("empty selection expression")
    ast, pos = _parse_or(tokens, 0)
    if pos != len(tokens):
        raise PredicateError(f"trailing tokens after expression: {tokens[pos:]}")
    return ast


def _parse_or(tokens, pos):
    node, pos = _parse_and(tokens, pos)
    while pos < len(tokens) and tokens[pos] == ("or", "or"):
        right, pos = _parse_and(tokens, pos + 1)
        node = ("or", node, right)
    return node, pos


def _parse_and(tokens, pos):
    node, pos = _parse_atom(tokens, pos)
    while pos < len(tokens) and tokens[pos] == ("and", "and"):
        right, pos = _parse_atom(tokens, pos + 1)
        node = ("and", node, right)
    return node, pos


def _parse_atom(tokens, pos):
    if pos >= len(tokens):
        raise PredicateError("unexpected end of expression")
    kind, value = tokens[pos]
    if kind == "(":
        node, pos = _parse_or(tokens, pos + 1)
        if pos >= len(tokens) or tokens[pos] != (")", ")"):
            raise PredicateError("missing closing parenthesis")
        return node, pos + 1
    if kind in ("field", "literal") and pos + 1 < len(tokens):
        op_kind = tokens[pos + 1][0]
        if op_kind in ("==", "contains"):
            if pos + 2 >= len(tokens) or tokens[pos + 2][0] not in ("field", "literal"):
                raise PredicateError(f"missing right-hand side after {op_kind}")
            rhs_kind, rhs_val = tokens[pos + 2]
            lhs = ("var", value) if kind == "field" else ("const", value)
            rhs = ("var", rhs_val) if rhs_kind == "field" else ("const", rhs_val)
            return (op_kind, lhs, rhs), pos + 3
    raise PredicateError(f"expected comparison near {value!r}")


# --------------------------------------------------------------------------
# Predicate evaluation
# --------------------------------------------------------------------------


def resolve_field(host: dict, name: str):
    """Field access: 'hostname' plus any fact key. Unknown fields -> None."""
    if name == "hostname":
        return host.get("hostname")
    return host.get("facts", {}).get(name)


def _contains(container, needle) -> bool:
    if isinstance(container, (list, tuple, set)):
        return needle in container
    if isinstance(container, str):
        return str(needle) in container
    return False


def evaluate(ast, host: dict) -> bool:
    op = ast[0]
    if op == "const":
        return bool(ast[1])  # pragma: no cover - only via odd expressions
    if op == "var":
        val = resolve_field(host, ast[1])
        return bool(val)
    if op == "or":
        return evaluate(ast[1], host) or evaluate(ast[2], host)
    if op == "and":
        return evaluate(ast[1], host) and evaluate(ast[2], host)
    if op == "==":
        return _resolve_operand(ast[1], host) == _resolve_operand(ast[2], host)
    if op == "contains":
        return _contains(_resolve_operand(ast[1], host), _resolve_operand(ast[2], host))
    raise PredicateError(f"unknown AST node: {op}")  # pragma: no cover


def _resolve_operand(node, host):
    return resolve_field(host, node[1]) if node[0] == "var" else node[1]


# --------------------------------------------------------------------------
# Fleet loading, selection, templating, execution
# --------------------------------------------------------------------------

FACT_RE = re.compile(r"\{(hostname|fact:[A-Za-z_][A-Za-z0-9_.-]*)\}")


def load_fleet(fleet_dir: Path) -> list[dict]:
    hosts = []
    for facts_path in sorted(fleet_dir.glob("*/facts.json")):
        facts = json.loads(facts_path.read_text())
        hosts.append({"hostname": facts_path.parent.name, "facts": facts})
    return hosts


def select_hosts(hosts: list[dict], expression: str) -> list[dict]:
    ast = parse(expression)
    return [h for h in hosts if evaluate(ast, h)]


def render_template(template: str, host: dict) -> str:
    def repl(m):
        key = m.group(1)
        if key == "hostname":
            return host["hostname"]
        assert key.startswith("fact:")
        fact_key = key[5:]
        if fact_key not in host["facts"]:
            raise KeyError(f"host {host['hostname']!r} has no fact {fact_key!r}")
        value = host["facts"][fact_key]
        return value if isinstance(value, str) else json.dumps(value)

    return FACT_RE.sub(repl, template)


def run_on_hosts(hosts: list[dict], fleet_dir: Path, template: str) -> dict:
    results = []
    for host in hosts:
        cmd = render_template(template, host)
        proc = subprocess.run(
            cmd, shell=True, cwd=fleet_dir / host["hostname"],
            capture_output=True, text=True,
        )
        results.append({
            "hostname": host["hostname"],
            "command": cmd,
            "exit_code": proc.returncode,
            "stdout": proc.stdout.strip(),
            "stderr": proc.stderr.strip(),
        })
    failures = [r for r in results if r["exit_code"] != 0]
    return {
        "selected": len(results),
        "ok": len(results) - len(failures),
        "failed": len(failures),
        "failures": failures,
        "results": results,
    }


# --------------------------------------------------------------------------
# CLI
# --------------------------------------------------------------------------


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Offline fleet simulator runner")
    parser.add_argument("--fleet", default="fleet", help="fleet directory (default: ./fleet)")
    parser.add_argument("--select", required=True, help="selection predicate expression")
    parser.add_argument(
        "command", nargs=argparse.REMAINDER,
        help="command template, after '--' (e.g. -- echo {hostname})",
    )
    args = parser.parse_args(argv)

    cmd = " ".join(args.command)
    if cmd.startswith("-- "):
        cmd = cmd[3:]
    if not cmd:
        parser.error("no command template given (use: fleetrun ... -- <template>)")

    try:
        hosts = load_fleet(Path(args.fleet))
        selected = select_hosts(hosts, args.select)
    except PredicateError as exc:
        print(f"selection error: {exc}", file=sys.stderr)
        return 2

    print(f"selected {len(selected)}/{len(hosts)} hosts: "
          f"{', '.join(h['hostname'] for h in selected) or '(none)'}")

    summary = run_on_hosts(selected, Path(args.fleet), cmd)

    for r in summary["results"]:
        status = "ok" if r["exit_code"] == 0 else f"FAILED({r['exit_code']})"
        print(f"\n[{r['hostname']}] $ {r['command']}  ->  {status}")
        if r["stdout"]:
            print(r["stdout"])
        if r["stderr"]:
            print(r["stderr"], file=sys.stderr)

    print(f"\nsummary: ok={summary['ok']} failed={summary['failed']}")
    if summary["failures"]:
        print("failures:", ", ".join(f["hostname"] for f in summary["failures"]))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

